/* GSA LIFE · browser UI */
(() => {
'use strict';
const E=window.GSAEngine, A=window.GSAAcademicUI.create(window.GSAEngine), P=window.GSAPeople, KEY='gsa-life-v1';
const R=window.GSARetrospectiveUI.create(E,P);
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',journal:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',cap:'m2 9 10-5 10 5-10 5z M6 11v6q6 5 12 0v-6 M22 9v8',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',ball:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3v18 M5.6 5.6q12 1 12.8 12.8 M5.6 18.4q1-12 12.8-12.8',flask:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M7 15h10',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13',flag:'M5 21V3q4-2 8 0t8 0v10q-4 2-8 0t-8 0',refresh:'M20 7V2 M20 7h-5 M20 7a9 9 0 1 0 1 9',arrow:'M4 12h16 m-6-6 6 6-6 6',check:'m4 12 5 5L20 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.spark}"/></svg>`}
let state=null,draft=E.create('새로운 학생'),view='home',action='study',mode='normal',semesterNotice=null,toastTimer,storageOK=true,commitment=null,shopCategory='all',courseDraft=[],courseDraftTerm=null,recapPage=0,recapMode='slides',recapOrigin='future';
try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);if([1,2,3,4,5,6].includes(v.version)&&v.state&&typeof v.state.turn==='number'&&v.state.stats&&Array.isArray(v.state.grades)){if(v.version<6&&!localStorage.getItem(KEY+'-v'+v.version+'-backup'))localStorage.setItem(KEY+'-v'+v.version+'-backup',raw);state=E.migrate(v.state);}}}catch(e){storageOK=false;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:6,state}));storageOK=true;}catch(e){storageOK=false;toast('저장 공간에 접근할 수 없어 이번 진행은 저장되지 않아요.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function clubName(list,id){return list.find(x=>x.id===id)?.name||'미가입'}
function shell(body){const nav=[['home','home','학교생활'],['life','heart','생활·매점'],['relationships','people','친구·연애'],['courses','book','수강·전공'],['grades','book','성적·수상'],['clubs','people','동아리·학생회'],['journal','journal','나의 기록'],['future','cap','진학·졸업'],...(state&&(state.turn>=42||!state.alive)?[['recap','spark','나의 회고']]:[])];$('#app').innerHTML=`<aside class="sidebar"><button type="button" class="brand brand-home" data-gx-title aria-label="시작 화면으로"><div class="brand-mark">g.</div><span>GSA LIFE</span></button><div class="brand-sub">THREE YEARS, YOUR STORY</div><div class="nav-label">MY SCHOOL LIFE</div><nav class="nav">${nav.map(([id,i,n])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${!state&&id!=='home'?'disabled':''} ${view===id?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><strong>정답이 없는 3년.</strong>어떤 학생으로 기억될지는<br>너의 선택에 달려 있어.</div><button class="new-btn" data-gx-title>${icon('home')}<span>시작 화면</span></button><button class="new-btn" data-do="new">${icon('refresh')}<span>새로운 학교생활</span></button></div></aside><main class="layout"><header class="topbar"><div class="breadcrumb"><span class="welcome-small">GSA LIFE &nbsp; / &nbsp; </span>나의 캠퍼스 &nbsp; / &nbsp; <b>${nav.find(n=>n[0]===view)?.[2]||(view==='recap'?'나의 회고':'입학하기')}</b></div><div class="top-right"><span class="save-status">${state?(storageOK?'이 브라우저에 자동 저장':'저장 사용 불가'):'나만의 3년을 시작해요'}</span>${window.GSAExtras?.helpButton()||''}<button class="new-mobile" data-do="new" aria-label="새로운 학교생활">↻</button>${P.toggleHTML()}${P.player(state||draft,{size:'tiny',label:'나의 캐릭터'})}</div></header>${body}<footer class="footer">광곽에서 살아남기 · GSA LIFE &nbsp; / &nbsp; 비공식 팬 시뮬레이터<br>학기당 7턴으로 압축한 비공식 게임입니다. 3학년 2학기 입시 일정, 수상 효과와 응급실·생존 판정은 게임 설정입니다.<br>${window.GSAExtras?.footerLinks()||''}</footer></main>`;bind();}
function statCards(s,cls='stats-grid'){
 const items=[['intelligence','지능','spark','교과 학습과 개념 이해'],['social','사회성','people','관계와 면접 소통'],['athletics','운동','ball','운동부 테스트와 훈련'],['discipline','자기관리','book','학습 습관과 준비'],['luck','행운','spark','테스트·면접의 기회'],['creativity','창의성','flask','연구와 새로운 제안'],['resilience','회복력','heart','피로 회복과 건강 관리'],['leadership','리더십','flag','학생회와 기장 선발']];
 return `<div class="${cls}">${items.map(([k,l,i,d])=>`<div class="card stat" title="${d}"><div class="stat-top">${icon(i)}${l}</div><div class="stat-value">${Math.round(s[k])}<small>/ 100</small></div><div class="bar" role="meter" aria-label="${l}" aria-valuenow="${Math.round(s[k])}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s[k]}%"></span></div></div>`).join('')}</div>`;
}
function typeCard(s){const t=E.archetypes.find(t=>t.id===s.archetype);return `<div class="type-card"><div><span class="eyebrow">MY CHARACTER TYPE</span><h3>${esc(t?.name||'나만의 성장형')}</h3><p>${esc(t?.description||'이전 학교생활을 이어가는 학생입니다. 쌓아온 성적과 활동은 그대로 유지됩니다.')}</p></div><span class="type-symbol">✦</span></div>`;}
function won(n){return `${Math.round(Number(n)||0).toLocaleString('ko-KR')}원`;}
function sportsNames(s){return s.sportsClubs.length?s.sportsClubs.map(id=>clubName(E.sportsClubs,id)).join(' · '):'운동부 미가입';}
function heading(k,t,d,tag='WEEKLY LIFE · v0.13'){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div><span class="tag">${tag}</span></div>`}
function setup(){shell(`${heading('YOUR NEXT CHAPTER','각자의 강점, 새로운 시작.','어떤 유형으로 태어나도, 3년의 선택은 네 몫이야.')}<section class="character-intro"><div class="intro-character">${P.player(draft,{size:'normal'})}</div><div><span class="eyebrow">광곽에서 살아남기</span><h2>입학부터 졸업까지, 어떤 학생이 될까?</h2><p>공부도, 친구도, 동아리도. 작은 선택을 쌓아 나만의 3년을 만들어봐.</p></div></section><div class="setup-columns"><section class="card setup-panel"><h2>나의 입학 카드</h2><p>유형에 따라 강점이 달라지고, 능력치는 범위 안에서 무작위로 정해져요.</p><div class="form-grid"><label class="field full">이름 또는 별명<input id="student-name" maxlength="16" placeholder="어떤 이름으로 기억될까?" autocomplete="off" value="${draft.name==='새로운 학생'?'':esc(draft.name)}"></label><label class="field">캐릭터 성별<select id="student-gender"><option value="">선택해주세요</option><option value="male">남자</option><option value="female">여자</option></select></label><label class="field">학술동아리<select id="academic-club">${E.academicClubs.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><small>질문과 실험으로 탐구 경험을 쌓아요.</small></label><label class="field">일반 상설동아리<select id="activity-club">${E.activityClubs.map(c=>`<option value="${c.id}" ${c.id==='none'?'selected':''}>${c.name}</option>`).join('')}</select><small>운동부는 입학 후 별도 테스트로 선발해요.</small></label></div><div class="row" style="margin-top:26px"><strong style="font-size:12px">무작위로 만난 나</strong><button class="secondary" data-do="reroll">↻ 유형과 능력치 다시 뽑기</button></div>${typeCard(draft)}${statCards(draft.stats,'setup-stats')}<div class="starting-wallet"><span>시작 자금</span><strong>${won(draft.money.balance)}</strong><small>초기 능력치와 균형을 맞춘 자금 · 매주 공통 용돈 ${won(draft.money.allowance)}</small></div><small style="font-size:10px">유형은 초기 강점이에요. 입학 후의 활동으로 다른 능력도 성장할 수 있어요.</small><button class="primary" data-do="start">입학하고 운동부 테스트 보기 ${icon('arrow')}</button></section><aside class="card setup-panel"><div class="eyebrow">NEW SCHOOL RULES</div><h2 style="margin-top:12px">이번 3년의 중요한 순간</h2>${[['01','1학년 첫 주 · 운동부 테스트','농구부와 축구부 중 한 곳에 지원해요. 운동 능력이 선발에 가장 크게 작용하고, 행운도 영향을 줍니다.'],['02','2학년 첫 주 · 두 번째 도전','아직 가입하지 않은 운동부에 지원할 수 있어요. 합격하면 두 운동부에서 함께 활동할 수도 있어요.'],['03','학생회와 기장 · 나의 역할','회장·부회장은 학생 공개질문에, 부서 임원은 면접에 응답해요. 기장은 1학년 말에 선출해 2학년 2학기 말까지, 학생회 임원은 다음 학년 1학기 말까지 활동해요.'],['04','탐사와 학교 밖의 이야기','제주·변산 자연탐사와 미국 글로벌 사이언스 챌린지. 현장연구학점을 쌓고 친구들과 새로운 장면을 만들어요.'],['05','진학과 졸업 · 서로 다른 관문','3학년 2학기에 대학 원서와 면접을 진행해요. TOEIC은 1학년부터 준비할 수 있고, 졸업에는 730점과 현장연구 6학점이 필요해요.']].map(([n,t,d])=>`<div class="step-note"><span class="step-num">${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}<div class="tip" style="margin-top:18px"><h3>한계에 닿기 전에 쉬어가기</h3><p>피로·스트레스 중 하나가 100 이상이거나 둘 다 90 이상이면 응급실 사건이 발생해요. 이 게임에는 생존과 사망으로 나뉘는 결말이 있습니다.</p></div></aside></div>`)}
function timeline(){const p=E.getPhase(state);return `<div class="timeline" aria-label="6학기 진행도">${Array.from({length:6},(_,i)=>`<div class="term ${i<Math.floor(state.turn/7)?'done':i===Math.floor(state.turn/7)?'current':''}"><span>${Math.floor(i/2)+1}학년 ${i%2+1}학기</span><small>${i<Math.floor(state.turn/7)?'완료':i===Math.floor(state.turn/7)?`${p.week} / 7주`:''}</small></div>`).join('')}</div>`}
function recentLog(limit=4){return state.log.slice(0,limit).map(l=>`<div class="journal-item"><small>${esc(l.label||(l.turn?`학교생활 ${l.turn}주차`:'입학 첫 주'))}</small><p>${esc(l.message||l.text||l)}</p></div>`).join('')||'<p style="font-size:11px;color:#8b977f">첫 번째 이야기를 기다리고 있어요.</p>'}
function profile(){const p=E.getProfile(state),type=E.archetypes.find(t=>t.id===state.archetype),d=E.getDormStatus(state);return `<section class="card profile"><div class="profile-head">${P.player(state,{size:'small'})}<div><strong>${esc(state.name)}</strong><small>${esc(type?.name||'나만의 성장형')} · ${esc(p.rankLabel)}</small></div><span class="ovr-badge" title="종합 능력치(OVR)"><b>${E.getOverall(state)}</b><small>OVR</small></span></div>${[['fatigue','피로도','fatigue'],['stress','스트레스','stress']].map(([k,l,c])=>`<div class="meter ${c} ${state.stats[k]>=90?'critical':''}"><div class="row"><span>${l}</span><b>${Math.round(state.stats[k])} <small>/ 한계 100</small></b></div><div class="bar threshold-bar"><span style="width:${Math.min(100,state.stats[k]/120*100)}%"></span><i></i></div></div>`).join('')}<div class="health-state ${state.illnessWeeks?'is-sick':''}"><strong>${state.illnessWeeks?`회복 중 · ${state.illnessWeeks}주`:'일상 생활 중'}</strong><span>피로·스트레스가 높다면 잠깐 쉬어가세요.</span></div><div class="dorm-status ${d.efficiency<1?'strained':''}"><strong>기숙사 · ${esc(d.label)}</strong><p>${esc(d.description)}</p><small>생활에 따른 학습 효율 ${Math.round(d.efficiency*100)}%</small></div><div class="profile-divider"></div><div class="metric"><span>내 지갑</span><strong>${won(state.money.balance)}</strong></div><div class="metric"><span>학급임원</span><strong>${esc(state.classRole||'일반 학생')}</strong></div><div class="metric"><span>현장연구학점</span><strong>${E.getFieldStatus(state).total} / 6</strong></div><div class="metric"><span>누적 평점</span><strong class="gpa">${state.grades.length?p.gpa.toFixed(2):'—'} <small style="font-size:10px">/ 4.3</small></strong></div><div class="metric"><span>연구 역량</span><strong>${Math.round(state.stats.research)}</strong></div><div class="metric"><span>학생회</span><strong>${esc(state.councilRole||'일반 학생')}</strong></div>${state.captain?`<div class="metric"><span>기장</span><strong>${esc(state.captainClub||'동아리')}</strong></div>`:''}<div class="profile-divider"></div><div class="metric"><span>TOEIC 최고점</span><strong>${state.toeic.best||'미응시'}${state.toeic.best?'점':''}</strong></div><div class="toeic-mini ${state.toeic.best>=730?'passed':''}">${state.toeic.best>=730?'졸업 영어 기준 충족':'졸업 기준 730점 · 1학년부터 준비 · 1학년 2학기부터 응시'}</div><div class="club-pill">${icon('flask')}${esc(clubName(E.academicClubs,state.academicClub))}</div><div class="club-pill">${icon('people')}${esc(clubName(E.activityClubs,state.activityClub))}</div><div class="club-pill sports-pill">${icon('ball')}${esc(sportsNames(state))}</div></section>`;}
function actionLocked(a){return Boolean(actionReason(a));}

function actionDescription(a){return actionReason(a)||a.description;}
function actionReason(a){return E.getActionDisabledReason?E.getActionDisabledReason(state,a.id):a.id==='sports'&&!state.sportsClubs.length?'운동부 테스트에 합격하면 참여할 수 있어요.':a.id==='toeic'&&state.turn<7?'1학년 2학기부터 응시할 수 있어요.':'';}

function awardsPanel(){const labels={contest:'교내 대회',sports:'교육감배',olympiad:'올림피아드',national_team:'국가대표',nationalTeam:'국가대표',academic:'교과우수상',subject:'교과우수상',model:'모범상',dorm_model:'기숙사모범상',dormModel:'기숙사모범상',dorm:'기숙사모범상'};return `<section class="card awards-panel"><div class="section-title"><h2>차곡차곡 쌓인 수상 기록</h2><small>${state.awards.length}개의 순간</small></div>${state.awards.length?`<div class="award-grid">${state.awards.map(a=>`<div class="award-card"><span>${a.kind==='sports'?'◉':['national_team','nationalTeam'].includes(a.kind)?'★':'✦'}</span><div><strong>${esc(a.name)}</strong><small>${a.year||Math.min(3,Math.floor(Math.max(0,(a.turn||1)-1)/16)+1)}학년${a.semester?` ${a.semester}학기`:''} · ${esc(labels[a.kind]||'학교생활')}</small></div></div>`).join('')}</div>`:'<p class="section-description">아직 수상 기록이 없어요. 학업과 탐구, 함께하는 생활 속에서 도전을 이어가보세요.</p>'}<div class="event-calendar"><span>교과우수상 · 과목별 상위 5%</span><span>매 학기 · 모범상과 기숙사모범상</span><span>올림피아드 · 국가대표 도전</span></div></section>`;}

function plannerOn(){const pl=state.studyPlanner;return !!(pl&&Array.isArray(pl.days)&&pl.days.some(d=>d.turn===state.turn));}
function plannerBox(p){const pl=state.studyPlanner,weeks=[...new Set(pl.days.map(d=>d.turn))],cur=E.plannerFractions(state,state.turn)||{nights:0,dawns:0};const L={none:['없음','기본 자습만'],night:['심야','피로 +11'],both:['심야+새벽','피로 +18']};return `<section class="exam-box planner-box"><div class="row"><h3>${esc(pl.examName)} 자습 플래너 · ${p.exam?'시험 주간':`${p.weeksToExam}주 전`}</h3></div><p>주마다 하나만 골라요. 새벽자습은 시험 1주 전부터 할 수 있어요. 연달아 무리하면 효과가 줄고, 시험 날 피로가 높으면 감점돼요.</p><div class="planner-weeks">${weeks.map(t=>{const wk=t%7+1,past=t<state.turn,now=t===state.turn,dawnOk=pl.examTurn-t<=1,lv=E.plannerWeekLevel(state,t);return `<div class="planner-week-row ${past?'is-past':''} ${now?'is-now':''}"><span class="planner-week">${wk}주차${t===pl.examTurn?' · 시험':''}${now?' <b>이번 주</b>':''}</span><div class="seg">${['none','night','both'].map(k=>`<button class="${lv===k?'on':''}" data-plan-week="${t}:${k}" ${past||(k==='both'&&!dawnOk)?'disabled':''} aria-pressed="${lv===k}"><b>${L[k][0]}</b><small>${k==='both'&&!dawnOk?'1주 전부터':L[k][1]}</small></button>`).join('')}</div></div>`;}).join('')}</div><div class="study-note">이번 주: ${cur.dawns?'심야+새벽자습':cur.nights?'심야자습':'추가 자습 없음'}</div></section>`;}
function studyPlan(p){if(plannerOn())return plannerBox(p);const enabled=p.availableStudyModes||['normal'];const options=[['normal','기본 자습','추가 피로 없음'],['night','심야 자습','시험 2주 전부터'],['dawn','새벽 자습','시험 1주 전부터'],['both','심야 + 새벽','준비와 피로 모두 ↑']];return `<section class="exam-box"><div class="row"><h3>${p.examName|| (p.week<=4?'중간고사':'기말고사')} · ${p.exam?'시험 주간':`${p.weeksToExam}주 전`}</h3><span class="tag">자습 일정</span></div><p>기본 수업·자습은 자동 진행됩니다. 추가 자습은 매주 선택하며, 교과 이해를 더 많이 쌓아 성적에 도움을 주고, 피로도 함께 올라가요.</p><div class="study-options">${options.map(([id,n,d])=>`<button data-mode="${id}" class="${mode===id?'active':''}" aria-pressed="${mode===id}" ${enabled.includes(id)?'':'disabled'}>${n}<small>${enabled.includes(id)?d:'아직 시작 전'}</small></button>`).join('')}</div><div class="study-note">${mode==='both'?'두 자습을 모두 선택했어요. 피로가 높은 상태라면 휴식도 고려해보세요.':mode==='night'?'심야자습으로 시험 준비도를 더 쌓아요. 피로도 함께 올라가요.':mode==='dawn'?'새벽자습으로 개념을 정리해요. 수면이 줄어 피로가 올라가요.':'오늘은 기본 자습을 하며 생활 리듬을 유지해요.'}</div></section>`;}
function actionInfo(a){if(a.id==='club'&&state.activityClub==='none')return {...a,name:'자율 활동',description:'내 시간을 확보하고 몸과 마음을 정돈해요.',effectsText:'피로 ↓ · 자기관리 ↑ · 스트레스 ↓'};return a;}
function weekReport(){const r=state.lastWeekReport;if(!r)return `<section class="card week-report first-report"><span class="eyebrow">YOUR WEEK, SIMULATED</span><h3>방향을 정하면, 일상이 움직여요.</h3><p>수업과 자습, 동아리, 운동, 친구와의 시간이 함께 흘러갑니다. 특별한 순간이 찾아오면 직접 선택해요.</p></section>`;const labels=E.statLabels||{intelligence:'지능',social:'사회성',athletics:'운동',discipline:'자기관리',research:'연구 역량',leadership:'리더십',creativity:'창의성',resilience:'회복력',fatigue:'피로도',stress:'스트레스'};return `<section class="card week-report"><div class="row"><div><span class="eyebrow">LAST WEEK</span><h3>지난주, 이렇게 보냈어.</h3></div><span class="tag">${esc(r.focusName)}</span></div><div class="week-deltas">${Object.entries(r.deltas||{}).filter(([k,v])=>k!=='health'&&Math.abs(v)>=.1).map(([k,v])=>`<span class="${['fatigue','stress'].includes(k)?'burden':''}">${esc(labels[k]||k)} <b>${v>0?'+':''}${Number(v).toFixed(1)}</b></span>`).join('')}</div><ul>${(r.activities||[]).map(a=>`<li>${esc(a)}</li>`).join('')}</ul>${Array.isArray(r.dailyEvents)?`<div class="week-daily"><b>이번 주 일상 사건 ${r.dailyEvents.length}건</b>${r.dailyEvents.length?`<ul>${r.dailyEvents.map(d=>`<li><span>${esc(d.title)}</span> ${esc(d.label)}${d.chosen?' <small>· 직접 선택</small>':''}</li>`).join('')}</ul>`:'<p>조용히 지나간 한 주였어.</p>'}</div>`:''}<div class="week-summary-bottom"><span>지갑 변화 ${r.moneyDelta>0?'+':''}${won(r.moneyDelta||0)}</span><span>사건 ${r.eventCount||0}건</span></div></section>`;}
function planParts(){const p=state.plan&&typeof state.plan==='object'?state.plan:{};const e=Object.entries(p).filter(([k,v])=>v>0&&E.focuses.some(f=>f.id===k)).sort((a,b)=>b[1]-a[1]);let main=e[0]?e[0][0]:(E.focuses.some(f=>f.id===state.focus)?state.focus:'balanced'),sub=e[1]?e[1][0]:null;if(e.length>2||(e.length===2&&!(e[0][1]===7&&e[1][1]===3))){sub=null;}return {main,sub};}
function weekPlan(){const {main,sub}=planParts(),plan=sub?{[main]:7,[sub]:3}:{[main]:10};state.plan=plan;state.focus=main;return plan;}
function focusPlan(){const plan=weekPlan(),{main,sub}=planParts();return `<section class="focus-section"><div class="section-title"><h2>이번 주 시간 배분</h2><small>다음 주에도 이어져요</small></div><p class="section-description">카드를 눌러 <b>주력</b> 활동을 골라요. 하나를 더 누르면 <b>보조</b>가 되어 시간을 7 : 3으로 나눠요. 보조를 다시 누르면 해제돼요.</p><div class="plan-meter"><div class="plan-bar">${[main,sub].filter(Boolean).map(id=>{const f=E.focuses.find(x=>x.id===id);return `<span class="plan-seg plan-seg--${id}" style="flex:${plan[id]}">${esc(f.name)} ${plan[id]*10}%</span>`;}).join('')}</div><div class="plan-meter-foot"><span>${sub?`주력 ${esc(E.focuses.find(f=>f.id===main).name)} 70% · 보조 ${esc(E.focuses.find(f=>f.id===sub).name)} 30%`:`${esc(E.focuses.find(f=>f.id===main).name)}에 집중 · 보조를 더하려면 다른 카드를 눌러요`}</span>${sub?'<button class="text-button" data-plan-swap>주력·보조 바꾸기</button>':''}</div></div><div class="focus-grid plan-grid">${E.focuses.map(f=>{const role=f.id===main?'main':f.id===sub?'sub':'';return `<button class="focus-card plan-card ${role?'selected':''} ${role?`plan-card--${role}`:''}" data-plan-pick="${f.id}" aria-pressed="${!!role}">${role?`<em class="plan-role">${role==='main'?'주력':'보조'}</em>`:''}<span class="focus-symbol">${icon(({balanced:'spark',intelligence:'book',social:'people',athletics:'ball',discipline:'clock',research:'flask',leadership:'flag',english:'journal',recovery:'moon'})[f.id]||'spark')}</span><strong>${esc(f.name)}</strong><p>${esc(f.description)}</p><small>${esc(f.effectsText||'')}</small></button>`;}).join('')}</div></section>`;}
function commitmentPlan(){if(commitment&&E.getCommitmentDisabledReason(state,commitment))commitment=null;return `<section class="card commitment-card"><div><h3>중요한 일정 예약</h3><p>필요할 때만 예약해요. 성장 방향과 함께 이번 주에 진행됩니다.</p></div><label class="field"><span class="sr-only">이번 주 예약 일정</span><select id="week-commitment"><option value="" ${!commitment?'selected':''}>예약 없이 일상 보내기</option><option value="toeic" ${commitment==='toeic'?'selected':''} ${E.getCommitmentDisabledReason(state,'toeic')?'disabled':''}>TOEIC 응시${state.turn<7?' · 1학년 2학기부터':''}</option><option value="fieldresearch" ${commitment==='fieldresearch'?'selected':''} ${E.getCommitmentDisabledReason(state,'fieldresearch')?'disabled':''}>개별 현장연구 1학점${E.getFieldStatus(state).independentCredits?' · 이수 완료':''}</option></select></label></section>`;}
function home(){if(!state.alive||state.turn>=42){future();return;}const p=E.getPhase(state);if(!E.focuses.some(f=>f.id===state.focus))state.focus='balanced';if(!p.availableStudyModes.includes(mode))mode='normal';const termLabel=`${p.year}학년 ${p.semester}학기`;const tips=state.stats.fatigue>=80||state.stats.stress>=80?'몸과 마음이 한계에 가까워요. 회복에 집중하고 추가 자습을 줄여보세요.':state.dorm.status==='expelled'?'통학으로 생활 리듬이 바뀌었어요. 이동에 드는 피로를 생각하며 성장 방향을 정해보세요.':E.getDormStatus(state).efficiency<1?'기숙사 생활이 편하지 않아 학습 효율이 떨어졌어요. 사회성을 키우고 대화의 기회를 선택해보세요.':state.illnessWeeks?'몸이 아픈 동안에는 학습과 활동 효율이 떨어져요. 회복에 집중해 몸을 돌봐주세요.':p.nightAvailable?'시험 준비 기간이에요. 추가 자습은 준비도를 높이지만 피로도 함께 쌓여요.':'집중할 능력치를 정하면 수업·동아리·운동과 친구와의 시간이 함께 흘러가요.';
shell(`${heading('A WEEK OF POSSIBILITIES',`${termLabel}, ${p.week}주차`,'시간을 나눠 쓰고, 나에게 찾아오는 한 주를 살아봐.',p.exam?'EXAM WEEK':'WEEKLY LIFE · v0.13')}${timeline()}<div class="columns"><div><button class="course-callout" data-nav="courses"><span><b>수업으로 그리는 나의 진로</b><small>${state.turn<21?'2학년 2학기부터 학기별 수강신청':'나의 시간표 · 이수학점 · 지원 가능한 전공'}</small></span>${icon('arrow')}</button>${focusPlan()}${commitmentPlan()}${studyPlan(p)}<button class="primary advance" data-do="advance"><span>이 계획으로 한 주 시뮬레이션</span><span class="advance-week"><small>WEEK ${state.turn+1} / 42</small>${icon('arrow')}</span></button><p class="action-foot">일상은 자동으로 · 중요한 순간에는 직접 선택 · 브라우저에 자동 저장</p>${weekReport()}<details class="card ability-details"><summary>나의 능력치 자세히 보기</summary>${statCards(state.stats)}</details></div><aside class="right-column">${profile()}<div class="tip"><h3>✦ 이번 주의 작은 조언</h3><p>${tips}</p></div><section class="card journal"><h3>최근의 순간들</h3>${recentLog()}</section></aside></div>`);}

function rankText(g){const r=g.rank||E.getClassRank(state,state.grades.indexOf(g));return r?` · 석차 ${r.semester}/${r.total} · 누적 ${r.cumulative}/${r.total}`:'';}
function scoreSplit(sub){if(sub.performance==null)return '';const parts=[`수행 ${Math.round(sub.performance)}`];if(sub.midtermScore!=null)parts.push(`중간 ${Math.round(sub.midtermScore)}`);if(sub.finalScore!=null)parts.push(`기말 ${Math.round(sub.finalScore)}`);if(sub.kind==='art')parts.push('시험 없음');return `<small class="score-split">${parts.join(' · ')}</small>`;}
function grades(){const p=E.getProfile(state);shell(`${heading('ACADEMIC RECORD','노력의 모양, 기록의 무게.','교과 성적과 학급에서의 역할, 매 학기의 수상을 함께 확인해요.','TRANSCRIPT & AWARDS')}${timeline()}<div class="summary-cards"><div class="card summary-card"><small>누적 평점 / 4.3</small><strong>${state.grades.length?p.gpa.toFixed(2):'—'}</strong></div><div class="card summary-card"><small>교과 이수 학점</small><strong>${p.credits}</strong></div><div class="card summary-card"><small>현장연구학점 / 6</small><strong>${E.getFieldStatus(state).total}</strong></div></div><details class="card source-notes grade-guide"><summary>등급 기준과 시상 방식</summary><p>높은 등급을 받으려면 과목 준비와 자기관리가 필요해요. 지능만 높거나 같은 활동을 반복한다고 점수가 계속 크게 오르지는 않으며, 선택과목의 난도와 피로·스트레스도 반영됩니다.</p><div class="grade-scale">${[['90','A+'],['85','A0'],['80','A−'],['75','B+'],['70','B0'],['65','B−'],['60','C+'],['55','C0'],['50','C−'],['45','D+'],['40','D0']].map(([score,grade])=>`<span><b>${grade}</b>${score}점 이상</span>`).join('')}<span><b>F</b>40점 미만</span></div><p>과목별 수강 인원의 5%를 올림한 수만큼 교과우수상을 수여해요. 여러 과목에서 각각 받을 수 있어요. 매 학기 각 반에서 모범상 3명, 기숙사모범상 3명을 선정합니다.</p><p>게임에는 가상 학생 96명, 반별 16명이 등장해요. 동점은 고정 학생 번호로 순서를 정합니다. 이전 저장의 확정된 성적은 보존하며 새 학기부터 새 등급 기준을 적용해요.</p><p><b>v0.13 점수 구성</b> · 수학·과학 이론: 수행 40 + 중간 30 + 기말 30 · 실험: 수행 60 + 기말 40 · 국어·영어·사회 등: 수행 60 + 지필 40 · 음악·미술·체육: 수행만 · 연구활동: 이수/미이수(평점 제외). 수행평가는 감점 사건이 없으면 만점이에요. 학기 석차는 학년 동기 90명 기준이에요.</p></details>${state.grades.length?state.grades.map(g=>{const term=(g.year-1)*2+g.semester-1,record=state.school.termResults.find(t=>t.year===g.year&&t.semester===g.semester);return `<details class="card details" open><summary><strong>${g.year}학년 ${g.semester}학기</strong><span>평점 ${g.gpa.toFixed(2)} · ${g.earnedCredits??g.credits}학점${rankText(g)}</span></summary><div class="table-wrap"><table><thead><tr><th>과목</th><th>학점</th><th>점수</th><th>등급</th><th>평점</th><th>석차 / 수강생</th><th>교과우수상</th></tr></thead><tbody>${g.subjects.map(sub=>{const r=record?.subjects.find(x=>x.id===sub.id);return `<tr><td>${esc(sub.name)}</td><td>${sub.credits}</td><td>${sub.score.toFixed(1)}${scoreSplit(sub)}</td><td>${esc(sub.grade)}</td><td>${sub.point.toFixed(1)}</td><td>${r?(r.rank==null?`수행평가 · ${r.enrollment}명`:`${r.rank} / ${r.enrollment}`):'—'}</td><td>${r?`${r.awarded?'✦ 수상':'—'} <small>(${r.lottery?`${r.quota}명 · 능력치 반영 추첨`:`상위 ${r.quota}명`})</small>`:'이전 기록'}</td></tr>`;}).join('')}</tbody></table></div>${(g.passFail||[]).length?`<p class="pf-note">이수/미이수 · ${g.passFail.map(c=>`${esc(c.name)} ${c.credits}학점 <b>${c.passed?'이수':'미이수'}</b>`).join(' · ')}</p>`:''}${record?semesterAwards(record):''}</details>`;}).join(''):'<div class="card empty">학기를 마치면 성적과 시상 결과가 이곳에 기록돼요.</div>'}${classPanel()}${awardsPanel()}`);}
function semesterAwards(r){const c=r.classes.find(c=>c.classId===state.school.classId)||r.classes[0];return `<div class="semester-awards"><div><b>우리 반 모범상 · 3명</b><p>${c.model.recipients.map(x=>esc(x.name)).join(' · ')}</p></div><div><b>우리 반 기숙사모범상 · 3명</b><p>${c.dormModel.recipients.map(x=>esc(x.name)).join(' · ')}</p></div></div>`;}
function classPanel(){return `<section class="card class-panel"><div class="section-title"><h2>우리 반의 이번 학기</h2><span class="tag">${esc(state.classRole||'일반 학생')}</span></div><p class="section-description">매 학기 반장·부반장·대의원을 새로 뽑아요. 학급임원 활동은 모범상 선정에 반영됩니다.</p>${state.school.officerHistory.length?state.school.officerHistory.map(h=>`<details class="mini-details"><summary>${h.year}학년 ${h.semester}학기 · 나의 역할: ${esc(h.playerRole||'일반 학생')}</summary><div class="officer-list">${h.roles.map(r=>`<div><small>${esc(r.role)}</small><strong>${esc(r.name)}</strong></div>`).join('')}</div></details>`).join(''):'<p class="section-description">이번 학기 학급임원 선출을 기다리고 있어요.</p>'}</section>`;}

function clubs(){shell(`${heading('BEYOND THE CLASSROOM','함께하는 곳, 성장하는 나.','운동장과 연구실, 기숙사에서 이어지는 너의 이야기.','CLUBS & COUNCIL')}${GSACurriculumGuide.render()}${classPanel()}<section class="card membership-section"><div class="section-title"><h2>나의 운동부</h2><span class="tag">최대 2개 소속</span></div><div class="sports-grid">${E.sportsClubs.map(c=>`<div class="sports-card ${state.sportsClubs.includes(c.id)?'joined':''}"><div class="row"><h3>${c.id==='basketball'?'◉':'⚽'} ${esc(c.name)}</h3><span class="tag">${state.sportsClubs.includes(c.id)?'선발 완료':'미가입'}</span></div><p>${esc(c.description)}</p><small>${state.sportsClubs.includes(c.id)?'팀 훈련은 일상에서 진행되고, 운동에 집중하면 더 성장해요.':'첫 주 테스트 또는 2학년 추가 모집에서 지원해요.'}</small></div>`).join('')}</div><p class="section-description">꾸준한 훈련과 실력으로 팀 안의 입지를 쌓아요. 매년 1학기가 끝나면 교육감배 대표에 도전할 수 있어요.</p><details class="mini-details"><summary>운동부 테스트 기록 (${state.sportsTryouts.length})</summary>${state.sportsTryouts.length?state.sportsTryouts.map(t=>`<div class="history-line"><span>${t.year}학년 · ${t.clubId?esc(clubName(E.sportsClubs,t.clubId)):'추가 지원 안 함'}</span><b>${!t.clubId?'미응시':t.passed?'합격':'불합격'}</b></div>`).join(''):'<p>아직 테스트 기록이 없어요.</p>'}</details></section><section class="card membership-section"><div class="section-title"><h2>학생회 · 2학기 모집</h2><span class="tag">현재: ${esc(state.councilRole)}</span></div><div class="council-years"><div><small>1학년 2학기</small><strong>학생회 부회장 / 각 부서 차장</strong></div><div><small>2학년 2학기</small><strong>학생회 회장 / 각 부서 부장</strong></div></div><p class="section-description">학생회 임원은 다음 학년 1학기 말까지 활동해요. 2학년 임원의 임기는 3학년 1학기 말에 끝나요.<br>회장·부회장: 학생들의 공개질문에 답하고 투표 결과를 기다려요.<br>각 부서 차장·부장: 부서 업무에 관한 면접을 진행해요.</p><div class="department-grid">${E.departments.map(d=>`<span>${esc(d.name)}</span>`).join('')}</div><details class="mini-details"><summary>나의 학생회 지원 기록 (${state.councilHistory.length})</summary>${state.councilHistory.length?state.councilHistory.map(h=>`<div class="history-line"><span>${h.year}학년 · ${esc(h.role)}</span><b>${h.role==='지원하지 않음'?'미지원':h.passed?'선발':'미선발'}</b></div>`).join(''):'<p>아직 지원 기록이 없어요. 1·2학년의 2학기에 지원할 수 있어요.</p>'}</details></section>${awardsPanel()}<div class="club-grid"><section class="card club-card"><div class="eyebrow">ACADEMIC CLUB</div><h3 style="margin-top:12px">${esc(clubName(E.academicClubs,state.academicClub))}</h3><p>친구들과 함께 질문하고 탐구해요. 전공 이해와 연구 경험을 쌓을 수 있어요.</p><span class="tag">연구 역량 ${Math.round(state.stats.research)} / 100</span></section><section class="card club-card"><div class="eyebrow">AFTER SCHOOL</div><h3 style="margin-top:12px">${esc(clubName(E.activityClubs,state.activityClub))}</h3><p>운동부와 별도로 선택한 일반 상설동아리예요. 자율 활동을 골랐다면 내 시간을 확보할 수 있어요.</p><span class="tag">${state.captain?`${esc(state.captainClub||'동아리')} 기장`:state.captainHistory?.some(h=>h.passed)?'기장 임기 종료 · 활동 기록 유지':'1학년 말 선출 · 2학년 말 임기 종료'}</span></section><section class="card club-card"><div class="eyebrow">MY DIRECTION</div><h3 style="margin-top:12px">나의 선택과목</h3><p>${state.turn>=21?E.getCurriculumStatus(state).currentSubjects.filter(c=>c.category).map(c=>esc(c.name)).join(' · '):'수강·전공에서 학기별 시간표와 지원 가능한 전공을 확인해요.'}</p></section><section class="card club-card"><div class="eyebrow">MY CHARACTER</div><h3 style="margin-top:12px">${esc(E.archetypes.find(t=>t.id===state.archetype)?.name||'나만의 성장형')}</h3><p>${esc(E.archetypes.find(t=>t.id===state.archetype)?.description||'이전의 학교생활을 이어가는 나만의 유형이에요.')}</p></section></div>`)}

function relationships(){const roster=E.getRomanceRoster(state),stageNames={none:'아직 알아가는 중',friendship:'친구',dating:'교제 중',ended:'관계를 마무리한 사이'},dating=roster.find(n=>n.dating),selected=roster.find(n=>n.selected);shell(`${heading('PEOPLE IN MY STORY','함께하는 사람들.','서로 다른 취향과 속도. 누군가를 조금 더 알아가는 시간.','FRIENDS & ROMANCE')}<section class="card relationship-overview"><div>${P.player(state,{size:'small'})}<div><h2>${dating?`${esc(dating.name)} · 교제 중`:'어떤 친구가 궁금해?'}</h2><p>${selected?`지금 더 알아가고 싶은 친구는 ${esc(selected.name)}. `:''}상대를 고르면 주간 생활 속에서 대화의 기회가 찾아와요.</p></div></div><button class="secondary" data-focus-link="social">사회성에 집중하기</button></section><div class="friend-grid">${roster.map(n=>`<article class="card friend-card ${n.selected?'selected':''} ${n.dating?'dating':''}"><div class="friend-top">${P.avatar(n.portraitIndex,{size:'normal',mood:n.id==='doyoon'?'sports':'idle',label:n.name})}<div><div class="row"><h2>${esc(n.name)}</h2>${n.dating?'<span class="friend-badge">♡ 교제 중</span>':n.selected?'<span class="friend-badge">관심 있는 친구</span>':''}</div><p>${esc(n.personality)}</p><small>${esc(Array.isArray(n.interests)?n.interests.join(' · '):n.interests)}</small></div></div><div class="friend-progress"><span>${stageNames[n.stage]||stageNames.none}</span><span>함께한 만남 ${n.meetings}회</span></div><div class="relationship-meter" aria-label="친밀도"><span style="width:${Math.max(0,Math.min(100,n.bond||0))}%"></span></div><button class="secondary" data-romance-target="${esc(n.id)}" ${n.selected||!n.canSelect?'disabled':''}>${n.selected?'지금 알아가는 친구':'더 알아가고 싶어'}</button>${!n.canSelect&&!n.selected&&n.disabledReason?`<small class="friend-disabled">${esc(n.disabledReason)}</small>`:''}</article>`).join('')}</div><p class="notice">친구마다 만남과 관계가 따로 기록돼요. 관심 대상을 바꾸어도 쌓아온 기억은 남고, 새로운 관계는 상대의 마음과 선택을 존중하며 천천히 이어집니다.</p>`);}

function life(){const d=E.getDormDiscipline(state),roster=E.getRomanceRoster(state),r=roster.find(n=>n.dating)||roster.find(n=>n.selected)||state.romance,stages={none:'새로운 만남을 기다리는 중',friendship:'조금씩 가까워지는 사이',dating:'함께하는 사이',ended:'각자의 일상으로'},live=state.alive&&state.turn<42,shop=E.getShop(state),cats=[['all','전체'],['drink','음료'],['food','먹거리'],['study','학습'],['sports','운동'],['life','생활']],owned=shop.filter(i=>i.owned);shell(`${heading('LIFE BETWEEN CLASSES','작은 소비, 달라지는 일상.','먹거리부터 오래 쓸 준비물까지. 지금 나에게 필요한 것을 골라봐.','CAMPUS SHOP')}<section class="wallet-hero"><div><span class="eyebrow">MY POCKET MONEY</span><h2>${won(state.money.balance)}</h2><p>공통 주간 용돈 ${won(state.money.allowance)} · 이번 주 매점 ${state.money.purchaseTurn===state.turn+(state.extraWeeks||0)?state.money.purchasesThisWeek:0} / 4회</p></div><span class="wallet-mark">₩</span></section><div class="section-title"><h2>학교 매점과 생활용품</h2><small>같은 물건은 한 주에 한 번 · 준비물은 한 번만 구매</small></div><div class="shop-filters" role="group" aria-label="매점 품목 분류">${cats.map(([id,label])=>`<button data-shop-category="${id}" aria-pressed="${shopCategory===id}" class="${shopCategory===id?'active':''}">${label}</button>`).join('')}</div><div class="shop-grid">${shop.filter(item=>shopCategory==='all'||item.category===shopCategory).map(item=>`<section class="card shop-card ${item.owned?'owned':''}"><div class="shop-symbol">${icon(({drink:'spark',food:'heart',study:'book',sports:'ball',life:'moon'})[item.category]||'spark')}</div><div class="shop-kind">${esc(item.categoryLabel||'매점')} · ${item.reusable?'한 번 준비':'소모품'}</div><h3>${esc(item.name)}</h3><p>${esc(item.description)}</p><small>${esc(item.effectsText||'')}</small><div class="row"><b>${won(item.price)}</b><button class="secondary" data-buy="${item.id}" ${item.disabledReason||!state.alive?'disabled':''}>${item.owned?'보유 중':'구매'}</button></div>${item.disabledReason?`<p class="shop-disabled">${esc(item.disabledReason)}</p>`:''}</section>`).join('')}</div>${owned.length?`<section class="card owned-gear"><h3>내가 준비한 물건</h3><div class="event-calendar">${owned.map(i=>`<span>${esc(i.name)}</span>`).join('')}</div></section>`:''}<div class="life-columns"><section class="card relationship-card"><span class="eyebrow">A LITTLE CLOSER</span>${P.avatar(r.portraitIndex??4,{size:'small',label:r.name||'친구'})}<h2>${stages[r.stage]||stages.none}</h2><p>${(r.name||r.partnerName)&&['friendship','dating'].includes(r.stage)?`친구 ${esc(r.name||r.partnerName)} · 함께 쌓아가는 이야기.`:'일상 속에서 마주치고, 대화하며 서로를 알아가요.'}</p><div class="relationship-meter"><span style="width:${Math.max(0,Math.min(100,r.bond))}%"></span></div><small>함께한 만남 ${r.meetings}회 · 관계는 서로의 마음에 따라 달라져요</small><button class="secondary" data-nav="relationships">친구들 만나러 가기</button></section><section class="card discipline-card"><span class="eyebrow">DORM LIFE</span><h2>${state.dorm.status==='expelled'?'기숙사 퇴사 · 통학 중':'기숙사 생활 기록'}</h2><p>${state.dorm.status==='expelled'?'적발 누적으로 기숙사를 떠났어. 통학하며 학교생활과 졸업 준비를 이어가요.':'배달이나 전자기기 사용을 선택하면 적발 여부를 따로 판정해요. 적발된 경우에만 기록이 쌓입니다.'}</p><div class="violation-row"><span>배달 적발</span><b>${state.dorm.deliveryCaught} / ${d.deliveryLimit}회</b></div><div class="violation-row"><span>전자기기 적발</span><b>${state.dorm.electronicsCaught} / ${d.electronicsLimit}회</b></div><small>배달 2회 또는 전자기기 4회 적발 시 기숙사 퇴사</small></section></div><div class="notice">배달 제안, 전자기기 사용, 친구와의 만남은 주간 생활 중 이벤트로 찾아와요. 그때 참여할지 직접 선택할 수 있어요.</div>${fieldPanel()}<details class="card source-notes"><summary>용돈 기록</summary>${state.money.ledger.slice(0,20).map(l=>`<div class="history-line"><span>${esc(l.label||l.reason||'용돈 기록')}</span><b>${Number(l.amount)>=0?'+':''}${won(l.amount)}</b></div>`).join('')}</details>`);}

function fieldPanel(){const f=E.getFieldStatus(state),ended=state.turn>=42,live=state.alive;return `<section class="card field-panel"><div class="row"><div><div class="eyebrow">FIELD RESEARCH</div><h2>교실 밖에서 채우는 6학점</h2></div><span class="field-total">${f.total}<small> / 6</small></span></div><div class="credit-dots">${Array.from({length:6},(_,i)=>`<span class="${i<f.total?'filled':''}" aria-label="${i+1}학점 ${i<f.total?'충족':'미충족'}"></span>`).join('')}</div><div class="trip-cards">${[['jeju','제주 자연탐사','1학년 2학기 중간고사 후','1학점'],['usa','미국 · 글로벌 사이언스 챌린지','2학년 여름 · 7박 9일','3학점'],['byeonsan','변산 자연탐사','2학년 2학기 중간고사 후','1학점']].map(([id,n,t,c])=>`<div><small>${t}</small><strong>${n}</strong><span>${c}</span></div>`).join('')}</div><p>학교 행사 ${f.schoolCredits} / 5학점 · 별도 현장연구 ${f.independentCredits} / 1학점</p><p class="section-description">학교 행사 모두 참여 시 5학점, 별도 현장연구로 1학점을 채워요. 행사별 1·3·1학점 배분은 게임용 설정입니다.</p>${live&&f.total<6?`<div class="retake-actions">${!ended&&f.canIndependent?'<button class="secondary" data-commitment="fieldresearch">이번 주 별도 현장연구 예약</button>':''}${ended?'<button class="primary" data-do="field-makeup">현장연구 요건 보완하기</button>':''}</div>`:''}${f.missingTrips.length?`<div class="notice">미참여 행사: ${f.missingTrips.map(t=>esc(t.name)).join(' · ')}<br>졸업 준비 기간에 보충 활동으로 채울 수 있어요.</div>`:''}<details class="mini-details"><summary>이수 기록 ${f.records.length}건</summary>${f.records.map(t=>`<div class="history-line"><span>${esc(t.name)}${t.makeup?' · 보충':''}</span><b>${t.credits}학점</b></div>`).join('')||'<p>현장연구 활동을 마치면 이곳에 기록돼요.</p>'}</details></section>`;}

function journal(){shell(`${heading('LITTLE MOMENTS','그때, 우리는.','작은 선택들이 모여 하나의 학교생활이 됩니다.','MY JOURNAL')}${recapLaunch()}<div class="card journal log-full">${recentLog(999)}</div>`)}
function courses(){shell(`${heading('COURSES TO POSSIBILITIES','내가 고른 수업, 이어지는 진로.','학기마다 시간표를 만들고, 배운 과목으로 다음 길을 열어봐.','COURSES & MAJORS')}${timeline()}${A.progress(state)}${A.currentPlan(state)}${A.makeup(state)}${A.majorCards(state)}${GSACurriculumGuide.render()}`);}
const universityGroups=[['sky','서울대 · 연세대 · 고려대'],['science','과학기술원 · POSTECH'],['seoul','서울권 대학'],['regional','지역 거점 대학']];
function universityCatalog(selectable=false){
 const options=selectable?E.getMajorOptions(state):[];
 return universityGroups.map(([id,label])=>{
  const universities=E.universities.filter(u=>u.group===id&&!u.legacy);if(!universities.length)return '';
  return `<details class="university-group" ${selectable||id==='sky'?'open':''}><summary><span>${esc(label)}</span><small>${universities.length}곳</small></summary><div class="university-grid">${universities.map(u=>{
   const status=E.getAdmissionStatus(state,u.id);
   return `<section class="university ${status.eligible?'':'university--below'}"><div class="university-level">게임 난이도 · ${esc(status.difficulty)}</div>${selectable?`<label class="university-pick"><input name="university" type="checkbox" value="${u.id}" data-exempt="${u.exempt?1:0}"><strong>${esc(u.name)}</strong></label>`:`<h3>${esc(u.name)}</h3>`}<p>${esc(u.description)}</p><div class="university-requirement">${esc(status.requirementText)}</div>${selectable&&!status.eligible?`<p class="university-warning">${esc(status.message)}</p>`:''}${selectable?`<label class="major-select-label">${esc(u.name)} 희망 전공<select name="major-${u.id}" data-major-for="${u.id}" disabled><option value="">전공을 선택하세요</option>${options.map(m=>`<option value="${m.id}" ${m.unlocked?'':'disabled'}>${esc(m.name)}${u.unit?'':` → ${esc(E.unitName(u.id,m.id))}`}${m.unlocked?'':` · ${esc(m.missing.join(', '))}`}</option>`).join('')}</select></label>`:''}</section>`;
  }).join('')}</div></details>`;
 }).join('');
}
function applicationForm(){const gpa=E.getProfile(state).gpa;return `<div class="admission-overview"><div><span class="eyebrow">MY ACADEMIC RECORD</span><strong>${gpa.toFixed(2)} <small>/ 4.3</small></strong></div><p>원서를 낼 때의 학년 누적 석차(동기 90명 중)로 학업을 평가하고, 연구·수상 기록과 면접을 더해요.<br>같은 대학이라도 컴퓨터·AI처럼 경쟁이 치열한 학과는 더 어려워요.</p></div><p class="application-help">수시 원서는 최대 6장(POSTECH 포함), 과학기술원(KAIST·GIST·DGIST·UNIST)은 따로 지원할 수 있어요. 면접은 서울대·KAIST·POSTECH·GIST·DGIST만 봐요. 높은 석차도 합격을 보장하지 않으니 도전과 안정을 섞어 보세요.</p>${universityCatalog(true)}<button class="primary" data-do="apply" style="margin-top:20px">대학과 전공을 정하고 원서 제출 ${icon('arrow')}</button><p class="form-hint">제출 후 대학과 전공은 변경할 수 없어요. 대학별 난이도와 합격 확률, 전공 조건은 실제 입시와 다른 게임 규칙입니다.</p>`;}

function applicationNames(){return (state.applications||[]).map(u=>{const id=typeof u==='string'?u:u.id;return `${clubName(E.universities,id)} · ${E.getMajor(state.applicationMajors?.[id]||'general')?.name||'자유탐색'}`;}).join(' / ');}
function toeicPanel(){const t=state.toeic,passed=t.best>=730;return `<section class="card toeic-panel"><div class="row"><div><div class="eyebrow">GRADUATION REQUIREMENT</div><h2>TOEIC · 졸업을 위한 한 걸음</h2></div><span class="tag">${passed?'기준 충족':'730점 필요'}</span></div><div class="toeic-score"><strong>${t.best||'—'}</strong><span>/ 990점</span><span class="goal">목표 730점</span></div><div class="toeic-progress"><span style="width:${t.best/990*100}%"></span><i style="left:${730/990*100}%"></i></div><p>${passed?'졸업 영어 기준을 충족했어요.':state.turn<7?'지금부터 성장 방향을 영어로 정해 TOEIC을 준비할 수 있어요. 응시는 1학년 2학기부터 가능해요.':'TOEIC 준비로 실력을 쌓고 응시해보세요. 지능과 행운도 점수에 영향을 줘요.'}</p>${state.turn<42&&state.alive?`<div class="retake-actions"><button class="secondary" data-focus-link="english">영어에 집중하기</button><button class="primary" data-commitment="toeic" ${state.turn<7?'disabled':''}>이번 주 TOEIC 응시 예약</button></div>`:''}${state.turn>=42&&state.alive&&!passed?`<div class="retake-actions"><button class="secondary" data-do="prepare-toeic">한 주 더 준비하기</button><button class="primary" data-do="retake-toeic">${t.attempts.length?'TOEIC 다시 응시하기':'TOEIC 응시하기'}</button></div><small>졸업 유예 ${state.extraWeeks||0}주 · 준비와 응시에도 시간이 흐릅니다.</small>`:''}<details class="mini-details"><summary>응시 기록 ${t.attempts.length}회</summary>${t.attempts.map((a,i)=>`<div class="history-line"><span>${i+1}회차</span><b>${a.score}점 ${a.score>=730?'· 통과':''}</b></div>`).join('')||'<p>아직 응시하지 않았어요.</p>'}</details></section>`;}
function admissionNotes(){return `<details class="card source-notes"><summary>면접 구성과 게임 설정 안내</summary><p>제출 서류·탐구 경험·수학과학 사고·진로와 협업을 살피는 공식 전형의 요소를 참고했습니다. 게임의 문항은 새로 만든 질문입니다.</p><p>3학년 2학기 지원·면접 일정, 올림피아드 수상에 따른 강한 과학기술원 합격 보정, 수상 인원과 탐사별 현장연구학점 배분은 이 게임의 설정입니다. 졸업에는 TOEIC 730점·현장연구 6학점과 선택 영역 이수 기준을 함께 적용합니다. 대학별 난이도와 학과별 경쟁 보정, 학년 석차 기반 합격 확률, 수시 6장 + 과학기술원 별도 지원, 면접 대학 범위, 전공별 지원 학점과 학기별 수강 범위는 게임 규칙입니다. 실제 대학별 일정과 전형을 재현한 예측기가 아닙니다.</p><a href="https://adm-u.unist.ac.kr/admission/community/rolling-admissions.do?articleNo=311513&amp;attachNo=594851&amp;mode=download" target="_blank" rel="noopener">UNIST 2027 탐구우수전형 면접 안내 ↗</a><a href="https://ewww.gist.ac.kr/uadm/html/sub03/0301.html?file_id=76657&amp;mode=D&amp;no=217495" target="_blank" rel="noopener">GIST 2027 입학전형 시행계획(안) ↗</a></details>`;}
function future(){if(!state.alive){deathScreen();return;}const p=E.getProfile(state),finished=state.turn>=42,passed=E.getGraduationStatus(state).eligible;
 let admissionBody='';if(state.admissions)admissionBody=admissionResults();else if(!state.applications?.length){admissionBody=state.turn>=35?`<div class="section-title"><h2>대학 원서 접수</h2><small>3학년 2학기 1주차</small></div>${applicationForm()}`:`<section class="card admission-preview"><div class="eyebrow">CHOOSE YOUR NEXT CHAPTER</div><h2>어떤 대학을 목표로 할까?</h2><p>원서는 3학년 2학기 1주차에 제출해요. 학년 석차와 연구, 면접에 따라 합격과 불합격이 갈립니다.</p><small>아래 난이도는 게임용 설정입니다. 서울대는 원서 제출 시 누적 평점 4.0 초과가 합격의 필수 조건이에요.</small></section>${universityCatalog()}`;}else{admissionBody=`<section class="card application-status"><div class="eyebrow">APPLICATION IN PROGRESS</div><h2>${state.admissionStage==='interview'?'면접이 진행 중이에요':state.admissionStage==='awaiting_results'?'면접을 마치고 결과를 기다려요':'원서를 제출했어요'}</h2><p>${esc(applicationNames())}</p><div class="admission-steps"><span class="done">원서 제출</span><span class="${state.admissionStage==='interview'?'current':state.admissionStage==='awaiting_results'?'done':''}">전공·연구 면접</span><span>합격 발표</span></div><small>제출 당시 누적 평점 ${Number(state.applicationSnapshot?.gpa??p.gpa).toFixed(2)} / 4.3 · 학교생활을 이어가면 면접과 발표가 찾아옵니다.</small></section>`;}
 shell(`${heading(finished?'MY ENDING':'THE NEXT CHAPTER',finished?(passed?'우리의 3년, 그리고 시작.':'마지막으로 채울 졸업 요건.'): '대학까지 이어지는 나의 이야기.',finished?(passed?'졸업 조건을 충족했어. 다음 페이지로 나아갈 시간.':'학교생활은 마쳤어. 영어 성적과 현장연구·선택과목 학점을 확인해보자.'):'3학년 2학기 원서와 면접, 그리고 졸업까지.',finished?(passed?'GRADUATED':'GRADUATION DEFERRED'):'ADMISSIONS & TOEIC')}${finished?recapLaunch():''}${finished?`<section class="graduation ${passed?'':'deferred'}"><div class="eyebrow">${esc(state.name)}의 ${passed?'졸업 앨범':'마지막 준비'}</div><h2>${passed?esc(p.strength):'졸업 유예 · 남은 요건 준비'}</h2><p>${passed?esc(p.ending):'대학 전형 결과와 별개로, TOEIC 730점, 현장연구 6학점과 선택 영역의 이수 기준을 모두 충족해야 졸업할 수 있어.'}<br>누적 평점 ${p.gpa.toFixed(2)} / 4.3 · 연구 역량 ${Math.round(state.stats.research)}</p></section>`:timeline()}${A.progress(state)}${A.makeup(state)}${toeicPanel()}${fieldPanel()}${admissionBody}${awardsPanel()}${admissionNotes()}${finished?'<button class="secondary" data-do="new" style="margin-top:22px">새로운 3년을 살아보기</button>':''}`);}
function deathScreen(){const p=E.getProfile(state);shell(`${heading('THE LAST PAGE','여기서 멈춘 학교생활.','응급실에서 치료를 받았지만, 이번 삶은 끝을 맞았어.','STORY ENDED')}${recapLaunch()}<section class="ending-card"><div class="ending-star">✧</div><h2>${esc(state.name)}의 이야기는<br>이곳에 남아 있어.</h2><p>함께 보낸 시간과 노력했던 순간들은 기록으로 남았어.<br>새로운 학교생활에서는 다른 선택을 해볼 수 있어.</p><div class="ending-stats"><span>${state.turn}주간의 기록</span><span>평점 ${p.gpa.toFixed(2)}</span><span>수상 ${state.awards.length}회</span></div><button class="primary" data-do="new">새로운 이야기 시작하기 ${icon('arrow')}</button></section><section class="card journal" style="margin-top:22px"><h3>마지막 기록</h3>${recentLog(6)}</section>`);}

function admissionResults(){const list=Array.isArray(state.admissions)?state.admissions:state.admissions?.results||[],graduated=state.ending==='graduated';return `<div class="section-title" style="margin-top:24px"><h2>대학 전형 결과</h2><small>게임 속 가상 결과</small></div>${list.map(r=>`<div class="card result"><div><h3>${esc(r.name||clubName(E.universities,r.id))}</h3><div class="result-major">${esc(r.majorName||E.getMajor(r.majorId||state.applicationMajors?.[r.id]||'general')?.name||'자유탐색')}</div><p>${esc(r.reason||'제출한 활동과 면접 결과를 함께 평가했습니다.')}</p>${r.accepted?`<small>${graduated?'졸업 조건 충족 · 진학 가능':'졸업 조건을 충족해야 진학할 수 있어요.'}</small>`:''}</div><span class="${r.accepted?'accepted':'rejected'}">${r.accepted?'합격':'불합격'}</span></div>`).join('')}${!list.some(r=>r.accepted)?'<p class="notice">이번 지원에서 합격 소식을 받지 못했어요. 졸업 후 새로운 진로와 다음 도전을 준비하는 결말로 이어집니다.</p>':''}`;}

function recapKey(){return !state?'':!state.alive?'death':state.turn>=42?(state.ending==='graduated'?'graduated':'deferred'):'';}
function recapLaunch(){const done=Boolean(recapKey());return `<section class="card recap-launch"><div><span class="eyebrow">MY SCHOOL STORY</span><h2>${done?'지나온 시간을 펼쳐볼까?':'지금까지, 어떤 시간을 보냈을까?'}</h2><p>${done?'장면을 하나씩 넘겨 보고, 마지막에는 한 장의 기록으로 만나봐.':'입학부터 지금까지의 기록을 차례로 돌아봐.'}</p></div><button class="primary" data-recap-open>나의 이야기 보기 ${icon('arrow')}</button></section>`;}
function recap(){shell(R.render(state,{page:recapPage,mode:recapMode}));}
function openRecap(){recapOrigin=view==='recap'?'future':view;recapPage=0;recapMode='slides';if(recapKey()){state.recapSeenEnding=recapKey();persist();}view='recap';render();$('#recap-title')?.focus();window.scrollTo({top:0,behavior:'instant'});}
function recapMove(direction){const last=Math.max(0,R.totalPages(state)-1);if(direction==='close'){view=recapKey()?'future':recapOrigin;render();window.scrollTo({top:0,behavior:'instant'});return;}if(direction==='replay'){recapPage=0;recapMode='slides';}else if(direction==='summary'){recapMode='summary';}else if(direction==='prev'){if(recapMode==='summary'){recapMode='slides';recapPage=last;}else recapPage=Math.max(0,recapPage-1);}else if(recapPage>=last){recapMode='summary';}else{recapPage++;}render();$('#recap-title')?.focus();window.scrollTo({top:0,behavior:'instant'});}
function bindRecap(){document.querySelectorAll('[data-recap-open]').forEach(b=>b.onclick=openRecap);for(const [attr,dir]of [['next','next'],['prev','prev'],['skip','summary'],['summary','summary'],['replay','replay'],['close','close']])document.querySelectorAll(`[data-recap-${attr}]`).forEach(b=>b.onclick=()=>recapMove(dir));document.querySelector('[data-recap-advance]')?.addEventListener('click',e=>{if(!e.target.closest('button,a,input,select,[role="button"]')&&!window.getSelection()?.toString())recapMove('next');});}
function render(){let started=false;if(state&&!state.alive)semesterNotice=null;if(state&&recapKey()&&state.recapSeenEnding!==recapKey()&&!state.pendingEvent&&!state.emergency&&!semesterNotice){state.recapSeenEnding=recapKey();persist();recapPage=0;recapMode='slides';view='recap';started=true;}if(!state)setup();else({home,life,relationships,courses,grades,clubs,journal,future,recap}[view]||home)();renderModal();P.refresh();if(started)$('#recap-title')?.focus();}
function getCourseDraft(){const o=E.getEnrollmentOptions(state);if(courseDraftTerm!==o.term){courseDraftTerm=o.term;courseDraft=[];}return courseDraft;}
function bindEnrollment(root){if(!root.querySelector('[name="course"]'))return;const refresh=()=>{root.querySelector('#enrollment-summary').innerHTML=A.selectionSummary(state,courseDraft);root.querySelector('[data-do="enroll"]').disabled=!E.validateEnrollment(state,courseDraft).valid;};root.querySelectorAll('[name="course"]').forEach(i=>i.onchange=()=>{courseDraft=[...root.querySelectorAll('[name="course"]:checked')].map(x=>x.value);i.closest('.course-choice').classList.toggle('selected',i.checked);refresh();});root.querySelectorAll('[data-recommend]').forEach(b=>b.onclick=()=>attempt(()=>{courseDraft=E.recommendEnrollment(state,b.dataset.recommend);root.querySelectorAll('[name="course"]').forEach(i=>{i.checked=courseDraft.includes(i.value);i.closest('.course-choice').classList.toggle('selected',i.checked);});refresh();toast('시간표 초안을 채웠어요. 확인한 뒤 확정하세요.');}));root.querySelector('[data-clear-courses]')?.addEventListener('click',()=>{courseDraft=[];root.querySelectorAll('[name="course"]').forEach(i=>{i.checked=false;i.closest('.course-choice').classList.remove('selected');});refresh();});}
function bindApplications(root){root.querySelectorAll('input[name="university"]').forEach(i=>i.onchange=()=>{if(root.querySelectorAll('input[name="university"][data-exempt="0"]:checked').length>6){i.checked=false;toast('수시 원서는 6장까지예요. 과학기술원(KAIST·GIST·DGIST·UNIST)은 따로 지원할 수 있어요.');}const sel=root.querySelector(`[data-major-for="${i.value}"]`);if(sel)sel.disabled=!i.checked;i.closest('.university').classList.toggle('chosen',i.checked);});}
function renderModal(){const root=$('#modal-root');root.innerHTML='';$('#app').inert=false;document.body.style.overflow='';if(!state||!state.alive||view==='recap')return;const p=E.getPhase(state);let html='',wide=false;
 if(state.pendingEvent&&(!(p.needsEnrollment||p.needsElectives)||state.pendingEvent.id==='emergency')){const e=state.pendingEvent;html=`${P.event(e,state)}<div class="eyebrow">A MOMENT TO CHOOSE</div><h2 id="modal-title">${esc(e.title)}</h2><p>${esc(e.description)}</p><div class="choices ${e.choices.length>6?'many-choices':''}">${e.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><strong>${esc(c.label)}</strong><small>${esc(c.description||'')}</small></button>`).join('')}</div>`;}
 else if(state.needsGender&&state.turn<42){html=`<div class="eyebrow">MY CHARACTER</div><h2 id="modal-title">캐릭터 성별을 선택해줘.</h2><p>지금까지의 성적과 활동은 그대로 이어집니다.</p><label class="field">성별<select id="saved-gender"><option value="male">남자</option><option value="female">여자</option></select></label><button class="primary" data-do="set-gender">선택하고 계속하기</button>`;}
 else if(p.needsEnrollment||p.needsElectives){const o=E.getEnrollmentOptions(state);wide=true;html=`<div class="eyebrow">BUILD YOUR SEMESTER</div><h2 id="modal-title">${o.year}학년 ${o.semester}학기 수강신청</h2><p>이번 학기에 배우고 싶은 과목을 골라봐. 이수한 선택과목은 대학에 지원할 수 있는 전공으로 이어져.</p>${A.catalogue(state,getCourseDraft())}`;}
 else if(p.needsApplications){wide=true;html=`<div class="eyebrow">A NEW CHAPTER</div><h2 id="modal-title">3학년 2학기,<br>대학과 전공을 선택할 시간.</h2><p>2학년 2학기에 이수한 과목으로 지원 가능한 전공이 정해져요. 원서를 제출하면 선택한 전공에 맞는 면접이 이어집니다.</p>${applicationForm()}`;}
 else if(semesterNotice){const g=semesterNotice;html=`<div class="eyebrow">ONE CHAPTER COMPLETE</div><h2 id="modal-title">${g.year}학년 ${g.semester}학기를 마쳤어.</h2><p>바쁘게 지나간 한 학기, 너의 노력이 기록되었어.</p><div class="summary-cards" style="grid-template-columns:1fr 1fr 1fr"><div class="card summary-card"><small>이번 학기 평점</small><strong>${g.gpa.toFixed(2)}</strong></div>${g.rank?`<div class="card summary-card"><small>석차 / ${g.rank.total}명</small><strong>${g.rank.semester}<small style="font-size:14px">등</small></strong><small>누적 ${g.rank.cumulative}등${g.rank.tie?' · 동점 있음':''}</small></div>`:''}<div class="card summary-card"><small>이수 학점</small><strong>${g.earnedCredits??g.credits}</strong></div></div><p>과목별 성적은 성적표에서, 전공 조건은 수강·전공에서 볼 수 있어요.</p><button class="primary" data-do="dismiss">${state.turn>=42?'나의 3년 돌아보기':'다음 이야기로'} ${icon('arrow')}</button>`;}
 if(html){$('#app').inert=true;document.body.style.overflow='hidden';root.innerHTML=`<div class="overlay"><section class="modal ${wide?'enrollment-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>attempt(()=>{const r=E.chooseEvent(state,Number(b.dataset.choice));persist();render();if(r?.messages?.length)toast(r.messages.join(' '));}));root.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));bindEnrollment(root);bindApplications(root);setTimeout(()=>[...root.querySelectorAll('[data-choice],summary,input,select,button:not([data-people-toggle])')].find(x=>!x.disabled&&x.getClientRects().length)?.focus(),0);}}
function attempt(fn){try{fn();}catch(e){toast(e.message||'선택을 다시 확인해주세요.');}}
function bind(){bindRecap();document.querySelectorAll('[data-romance-target]').forEach(b=>b.onclick=()=>attempt(()=>{const r=E.selectRomanceTarget(state,b.dataset.romanceTarget);persist();render();if(r?.messages?.length)toast(r.messages.join(' '));}));$('#student-gender')?.addEventListener('change',e=>{const target=$('.intro-character');if(target){target.innerHTML=P.player({...draft,gender:e.target.value},{size:'normal'});P.refresh();}});document.querySelectorAll('[data-plan-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.planPick,{main,sub}=planParts();let m=main,u=sub;if(id===m){if(u){m=u;u=null;}}else if(id===u)u=null;else if(!u)u=id;else u=id;state.plan=u?{[m]:7,[u]:3}:{[m]:10};state.focus=m;persist();render();});document.querySelectorAll('[data-plan-swap]').forEach(b=>b.onclick=()=>{const {main,sub}=planParts();if(sub){state.plan={[sub]:7,[main]:3};state.focus=sub;persist();render();}});document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{state.focus=b.dataset.focus;state.plan={[b.dataset.focus]:E.PLAN_BLOCKS||10};persist();render();});document.querySelectorAll('[data-focus-link]').forEach(b=>b.onclick=()=>{state.focus=b.dataset.focusLink;state.plan={[b.dataset.focusLink]:E.PLAN_BLOCKS||10};view='home';persist();render();window.scrollTo({top:0,behavior:'instant'});});document.querySelectorAll('[data-commitment]').forEach(b=>b.onclick=()=>{const reason=E.getCommitmentDisabledReason(state,b.dataset.commitment);if(reason){toast(reason);return;}commitment=b.dataset.commitment;view='home';render();$('.commitment-card')?.scrollIntoView({block:'center',behavior:'smooth'});toast('이번 주 일정을 예약했어요. 한 주 시뮬레이션으로 진행하세요.');});document.querySelectorAll('[data-shop-category]').forEach(b=>b.onclick=()=>{shopCategory=b.dataset.shopCategory;render();});$('#week-commitment')?.addEventListener('change',e=>{commitment=e.target.value||null;});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>attempt(()=>{const r=E.buyItem(state,b.dataset.buy);persist();render();if(r?.messages?.length)toast(r.messages.join(' '));}));document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const a=E.actions.find(a=>a.id===b.dataset.plan);if(!a||actionLocked(a)){toast(a?actionReason(a):'활동을 확인해주세요.');return;}action=a.id;view='home';render();$('.advance')?.scrollIntoView({block:'center',behavior:'smooth'});toast(`${a.name}을 선택했어요. 한 주 보내기로 진행하세요.`);});$('[data-do="start"]')?.addEventListener('click',()=>dispatch('start'));document.querySelectorAll('.layout [data-do]:not([data-do="start"]),.sidebar [data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='recap'){openRecap();return;}view=b.dataset.nav;render();window.scrollTo({top:0,behavior:'instant'});});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{action=b.dataset.action;render();});document.querySelectorAll('[data-plan-week]').forEach(b=>b.onclick=()=>attempt(()=>{const [t,k]=b.dataset.planWeek.split(':');E.setStudyPlannerWeek(state,+t,k);persist();render();}));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});bindApplications(document);}
function dispatch(what){attempt(()=>{if(what==='reroll'){const name=$('#student-name').value,ac=$('#academic-club').value,act=$('#activity-club').value,gender=$('#student-gender').value;draft=E.create(name||'새로운 학생');render();$('#academic-club').value=ac;$('#activity-club').value=act;$('#student-gender').value=gender;return;}if(what==='start'){const gender=$('#student-gender').value;if(!gender){toast('캐릭터의 성별을 선택해주세요.');return;}E.setGender(draft,gender);draft.name=$('#student-name').value.trim()||'새로운 학생';E.setClubs(draft,$('#academic-club').value,$('#activity-club').value);state=draft;view='home';persist();render();window.scrollTo({top:0,behavior:'instant'});return;}if(what==='new'){if(state&&!confirm('현재 진행을 지우고 새로운 학교생활을 시작할까요?'))return;state=null;draft=E.create('새로운 학생');view='home';action='study';commitment=null;shopCategory='all';mode='normal';semesterNotice=null;recapPage=0;recapMode='slides';recapOrigin='future';try{localStorage.removeItem(KEY);}catch(e){}render();window.scrollTo({top:0,behavior:'instant'});return;}if(what==='set-gender'){E.setGender(state,$('#saved-gender').value);persist();render();return;}if(what==='field-makeup'){const r=E.makeupFieldTrip(state);persist();render();if(r?.messages?.length)toast(r.messages.join(' '));return;}if(what==='advance'){const result=E.simulateWeek(state,weekPlan(),plannerOn()?'normal':mode,commitment);mode='normal';commitment=null;if(result.semesterResult)semesterNotice=result.semesterResult;persist();render();if(result.messages?.length)toast(result.messages.slice(0,2).join(' '));return;}if(what==='enroll'){E.enrollSemester(state,courseDraft);courseDraft=[];courseDraftTerm=null;persist();render();toast('수강신청을 확정했어요. 이번 학기 수업이 시작됩니다.');return;}if(what==='course-makeup'){const r=E.makeupCourse(state,$('#makeup-course').value);persist();render();if(r?.messages?.length)toast(r.messages.join(' '));return;}if(what==='dismiss'){semesterNotice=null;if(state.turn>=42)view='future';render();return;}if(what==='retake-toeic'||what==='prepare-toeic'){const r=what==='retake-toeic'?E.takeToeic(state):E.prepareToeic(state);persist();render();if(r?.messages?.length)toast(r.messages.join(' '));return;}if(what==='apply'){const scope=$('.modal')||document;const ids=[...scope.querySelectorAll('input[name="university"]:checked')].map(i=>i.value);if(!ids.length){toast('지원할 대학을 1곳 이상 선택해주세요.');return;}const applications=ids.map(id=>({universityId:id,majorId:scope.querySelector(`[data-major-for="${id}"]`).value}));if(applications.some(a=>!a.majorId)){toast('선택한 대학마다 희망 전공을 골라주세요.');return;}E.applyUniversities(state,applications);persist();render();return;}});}
document.addEventListener('keydown',e=>{if(view==='recap'&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!e.target.closest('input,textarea,select')){if(['ArrowRight','ArrowLeft','Escape'].includes(e.key)){e.preventDefault();recapMove(e.key==='ArrowRight'?'next':e.key==='ArrowLeft'?'prev':'close');return;}}const modal=$('.modal');if(!modal||e.key!=='Tab')return;const targets=[...modal.querySelectorAll('button,input,select,summary,[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length);const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
function resetGame(){state=null;draft=E.create("새로운 학생");view="home";action="study";commitment=null;shopCategory="all";mode="normal";semesterNotice=null;recapPage=0;recapMode="slides";recapOrigin="future";courseDraft=[];courseDraftTerm=null;try{localStorage.removeItem(KEY);}catch(e){}render();window.scrollTo({top:0,behavior:"instant"});}
window.GSAApp={getState:()=>state,reset:resetGame,render:()=>render()};
render();
window.GSAExtras?.init();window.GSAShareCard?.init();window.GSATitle?.init();
})();
